52	// Data structure collecting aggregate transformation metrics for the IR.  These
53	// values are zero-ed at construction time and only increment.
54	struct TransformMetrics {
55	  // Number of nodes added (number of invocations of
56	  // FunctionBase::AddNodeInternal).
57	  int64_t nodes_added = 0;
58	
59	  // Number of nodes removed (number of invocations of
60	  // FunctionBase::RemoveNode).
61	  int64_t nodes_removed = 0;
62	
63	  // Number of nodes replaced (number of calls to Node::ReplaceUsesWith).
64	  int64_t nodes_replaced = 0;
65	
66	  // Number of operands replaced (number of calls to
67	  // Node::ReplaceOperand[Number]).
68	  int64_t operands_replaced = 0;
69	
70	  // Number of operands removed (number of calls to
71	  // Node::RemoveOptionalOperand).
72	  int64_t operands_removed = 0;
73	
74	  static TransformMetrics FromProto(const TransformMetricsProto& proto);
75	  TransformMetrics operator+(const TransformMetrics& other) const;
76	  TransformMetrics operator-(const TransformMetrics& other) const;
77	  std::string ToString() const;
78	  TransformMetricsProto ToProto() const;
79	};
80	
81	class Package {
82	 public:
83	  explicit Package(std::string_view name);
84	
85	  // Note: functions have parent pointers to their packages, so we don't want
86	  // them to be moved or copied; this makes Package non-moveable non-copyable.
87	  // If a copy is required one can explicitly use ClonePackage in
88	  // clone_package.h.
89	  Package(const Package& other) = delete;
90	  Package& operator=(const Package& other) = delete;
91	
92	  virtual ~Package();
93	
94	  std::optional<FunctionBase*> GetTop() const;
95	  bool HasTop() const { return top_.has_value(); }
96	  // Sets the top entity of the package.
97	  absl::Status SetTop(std::optional<FunctionBase*> top);
98	  // Sets the top to a FunctionBase with its name equivalent to the 'top_name'
99	  // parameter. The function calls xls::Package::SetTop function. Prerequisite:
100	  // a single function base with the with its name equivalent to the 'top_name'
101	  // parameter must exist.
102	  absl::Status SetTopByName(std::string_view top_name);
103	
104	  // Returns true if the package's top is set to `f`.
105	  bool IsTop(const FunctionBase* f) const {
106	    return top_.has_value() && f == *top_;
107	  }
108	
109	  // Helper function to get the top as a function, proc or block.
110	  absl::StatusOr<Function*> GetTopAsFunction() const;
111	  absl::StatusOr<Proc*> GetTopAsProc() const;
112	  absl::StatusOr<Block*> GetTopAsBlock() const;
113	
114	  // Returns a FunctionBase with the given name if a single instance exists.
115	  absl::StatusOr<FunctionBase*> GetFunctionBaseByName(
116	      std::string_view name) const;
117	
118	  TypeManager& type_manager() { return type_manager_; }
119	  const TypeManager& type_manager() const { return type_manager_; }
120	  // Returns whether the given type is one of the types owned by this package.
121	  bool IsOwnedType(const Type* type) const {
122	    return type_manager_.IsOwnedType(type);
123	  }
124	  bool IsOwnedFunctionType(const FunctionType* function_type) const {
125	    return type_manager_.IsOwnedFunctionType(function_type);
126	  }
127	
128	  BitsType* GetBitsType(int64_t bit_count) {
129	    return type_manager_.GetBitsType(bit_count);
130	  }
131	  ArrayType* GetArrayType(int64_t size, Type* element_type) {
132	    return type_manager_.GetArrayType(size, element_type);
133	  }
134	  TupleType* GetTupleType(absl::Span<Type* const> element_types) {
135	    return type_manager_.GetTupleType(element_types);
136	  }
137	  TokenType* GetTokenType() { return type_manager_.GetTokenType(); }
138	  FunctionType* GetFunctionType(absl::Span<Type* const> args_types,
139	                                Type* return_type) {
140	    return type_manager_.GetFunctionType(args_types, return_type);
141	  }
142	
143	  // Returns a pointer to a type owned by this package that is of the same
144	  // type as 'other_package_type', which may be owned by another package.
145	  absl::StatusOr<Type*> MapTypeFromOtherPackage(Type* other_package_type) {
146	    return type_manager_.MapTypeFromOtherArena(other_package_type);
147	  }
148	
149	  // Creates and returned an owned type constructed from the given proto.
150	  absl::StatusOr<Type*> GetTypeFromProto(const TypeProto& proto) {
151	    return type_manager_.GetTypeFromProto(proto);
152	  }
153	  absl::StatusOr<FunctionType*> GetFunctionTypeFromProto(
154	      const FunctionTypeProto& proto) {
155	    return type_manager_.GetFunctionTypeFromProto(proto);
156	  }
157	
158	  Type* GetTypeForValue(const Value& value) {
159	    return type_manager_.GetTypeForValue(value);
160	  }
161	
162	  // Add a function, proc, or block to the package. Ownership is transferred to
163	  // the package.
164	  Function* AddFunction(std::unique_ptr<Function> f);
165	  Proc* AddProc(std::unique_ptr<Proc> proc);
166	  Block* AddBlock(std::unique_ptr<Block> block);
167	
168	  // Return a new name-uniquer that will generate unique names for top-level
169	  // constructs in this package. Note that this uniquer will not track what is
170	  // actually present in the package after creation.
171	  NameUniquer NameUniquerForPackage() const;
172	
173	  struct PackageMergeResult {
174	    // other package -> this package name mapping (channels, procs, functions,
175	    // and blocks)
176	    absl::flat_hash_map<std::string, std::string> name_updates;
177	    // other package -> this package channel id mapping
178	    absl::flat_hash_map<std::string, std::string> channel_updates;
179	  };
180	  // Import all IR constructs from another package to this package. Ownership of
181	  // all constructs is transferred to this package.
182	  absl::StatusOr<PackageMergeResult> ImportFromPackage(const Package* other);
183	
184	  // Get a function, proc, or block by name. Returns an error if no such
185	  // construct of the indicated kind exists with that name.
186	  absl::StatusOr<Function*> GetFunction(std::string_view func_name) const;
187	  absl::StatusOr<Proc*> GetProc(std::string_view proc_name) const;
188	  absl::StatusOr<Block*> GetBlock(std::string_view block_name) const;
189	
190	  // Gets a function, proc, or block by name. Returns nullopt if no such
191	  // construct of the indicated kind exists with that name.
192	  std::optional<Function*> TryGetFunction(std::string_view func_name) const;
193	  std::optional<Proc*> TryGetProc(std::string_view proc_name) const;
194	  std::optional<Block*> TryGetBlock(std::string_view block_name) const;
195	
196	  // Remove a function, proc, or block. The caller is responsible for ensuring
197	  // no references to the construct remain (e.g., via invoke operations). The
198	  // function, proc, or block must not be the top entity of the package. Use the
199	  // xls::Package::UnsetTop function to unset the top. The function, proc, or
200	  // block cannot be nullptr.
201	  absl::Status RemoveFunctionBase(FunctionBase* function_base);
202	  absl::Status RemoveFunction(Function* function);
203	  absl::Status RemoveProc(Proc* proc);
204	  absl::Status RemoveBlock(Block* block);
205	
206	  // Returns a new SourceLocation object containing a Fileno and Lineno pair.
207	  // SourceLocation objects are added to XLS IR nodes and used for debug
208	  // tracing.
209	  //
210	  // An example of how this function  might be used from C++ is shown below:
211	  // __FILE__ and __LINE__ macros are passed as arguments to a SourceLocation
212	  // builder and the result is passed to a Node builder method:
213	  //
214	  //   SourceLocation loc = package.AddSourceLocation(__FILE__, __LINE__)
215	  //   function_builder.SomeNodeType(node_args, loc);
216	  //
217	  // An alternative front-end could instead call AddSourceLocation with the
218	  // appropriate metadata annotated on the front-end AST.
219	  //
220	  // If the file "filename" has been seen before, the Fileno is retrieved from
221	  // an internal lookup table, otherwise a new Fileno id is generated and added
222	  // to the table.
223	  // TODO(dmlockhart): update to use ABSL_LOC and xabsl::SourceLocation.
224	  SourceLocation AddSourceLocation(std::string_view filename, Lineno lineno,
225	                                   Colno colno);
226	
227	  // Translates a SourceLocation object into a human readable debug identifier
228	  // of the form: "<source_file_path>:<line_number>".
229	  std::string SourceLocationToString(const SourceLocation& loc);
230	
231	  // Retrieves the next node ID to assign to a node in the package and
232	  // increments the next node counter. For use in node construction.
233	  int64_t GetNextNodeIdAndIncrement() { return next_node_id_++; }
234	
235	  // Adds a file to the file-number table and returns its corresponding number.
236	  // If it already exists, returns the existing file-number entry.
237	  Fileno GetOrCreateFileno(std::string_view filename);
238	
239	  // Forcibly sets a given file number to map to a given file.
240	  // Used when parsing a `Package`.
241	  void SetFileno(Fileno file_number, std::string_view filename);
242	
243	  // Get the filename corresponding to the given `Fileno`.
244	  std::optional<std::string> GetFilename(Fileno file_number) const;
245	
246	  const absl::flat_hash_map<Fileno, std::string>& fileno_to_name() const {
247	    return fileno_to_filename_;
248	  }
249	
250	  // Returns the total number of nodes in the graph. Traverses the functions,
251	  // procs and blocks and sums the node counts.
252	  int64_t GetNodeCount() const;
253	  // Returns the total number of nodes in the blocks in the graph. Traverses the
254	  // blocks and sums the node counts.
255	  int64_t GetBlockNodeCount() const;
256	  // Returns the total number of nodes in the functions in the graph. Traverses
257	  // the functions and sums the node counts.
258	  int64_t GetFunctionNodeCount() const;
259	  // Returns the total number of nodes in the procs in the graph. Traverses the
260	  // procs and sums the node counts.
261	  int64_t GetProcNodeCount() const;
262	
263	  // Returns the functions in this package.
264	  absl::Span<std::unique_ptr<Function>> functions() {
265	    return absl::MakeSpan(functions_);
266	  }
267	  absl::Span<const std::unique_ptr<Function>> functions() const {
268	    return functions_;
269	  }
270	
271	  // Returns the procs in this package.
272	  absl::Span<std::unique_ptr<Proc>> procs() { return absl::MakeSpan(procs_); }
273	  absl::Span<const std::unique_ptr<Proc>> procs() const { return procs_; }
274	
275	  // Returns the blocks in this package.
276	  absl::Span<std::unique_ptr<Block>> blocks() {
277	    return absl::MakeSpan(blocks_);
278	  }
279	  absl::Span<const std::unique_ptr<Block>> blocks() const { return blocks_; }
280	
281	  // Returns the procs, functions, and blocks in this package (all types derived
282	  // from FunctionBase).
283	  // TODO(meheff): Consider holding functions and procs in a common vector.
284	  std::vector<FunctionBase*> GetFunctionBases() const;
285	
286	  const std::string& name() const { return name_; }
287	
288	  // Returns true if analysis indicates that this package always produces the
289	  // same value as 'other' when run with the same arguments. The analysis is
290	  // conservative and false may be returned for some "equivalent" packages.
291	  bool IsDefinitelyEqualTo(const Package* other) const;
292	
293	  // Dumps the IR in a parsable text format.
294	  std::string DumpIr() const;
295	
296	  std::vector<std::string> GetFunctionNames() const;
297	
298	  int64_t next_node_id() const { return next_node_id_; }
299	
300	  // Intended for use by the parser when node ids are suggested by the IR text.
301	  void set_next_node_id(int64_t value) { next_node_id_ = value; }
302	
303	  // Create a channel. Channels are used with send/receive nodes in communicate
304	  // between procs or between procs and external (to XLS) components. If no
305	  // channel ID is specified, a unique channel ID will be automatically
306	  // allocated.
307	  // TODO(meheff): Consider using a builder for constructing a channel.
308	  absl::StatusOr<StreamingChannel*> CreateStreamingChannel(
309	      std::string_view name, ChannelOps supported_ops, Type* type,
310	      absl::Span<const Value> initial_values = {},
311	      ChannelConfig channel_config = ChannelConfig(),
312	      FlowControl flow_control = FlowControl::kReadyValid,
313	      ChannelStrictness strictness = kDefaultChannelStrictness,
314	      std::optional<int64_t> id = std::nullopt);
315	
316	  // Create a channel without special flop control. Channels are used with
317	  // send/receive nodes in communicate between procs or between procs and
318	  // external (to XLS) components. If no channel ID is specified, a unique
319	  // channel ID will be automatically allocated.
320	  // TODO(meheff): Consider using a builder for constructing a channel.
321	  absl::StatusOr<StreamingChannel*> CreateStreamingChannel(
322	      std::string_view name, ChannelOps supported_ops, Type* type,
323	      absl::Span<const Value> initial_values,
324	      std::optional<FifoConfig> fifo_config,
325	      FlowControl flow_control = FlowControl::kReadyValid,
326	      ChannelStrictness strictness = kDefaultChannelStrictness,
327	      std::optional<int64_t> id = std::nullopt) {
328	    return CreateStreamingChannel(
329	        /*name=*/name, /*supported_ops=*/supported_ops, /*type=*/type,
330	        /*initial_values=*/initial_values,
331	        /*channel_config=*/
332	        ChannelConfig(fifo_config, std::nullopt, std::nullopt),
333	        /*flow_control=*/flow_control, /*strictness=*/strictness,
334	        /*id=*/id);
335	  }
336	
337	  absl::StatusOr<SingleValueChannel*> CreateSingleValueChannel(
338	      std::string_view name, ChannelOps supported_ops, Type* type,
339	      std::optional<int64_t> id = std::nullopt);
340	
341	  // Variants which add a channel on a proc for new style procs.
342	  // TODO(https://github.com/google/xls/issues/869): Move these methods to
343	  // xls::Proc.
344	  absl::StatusOr<StreamingChannel*> CreateStreamingChannelInProc(
345	      std::string_view name, ChannelOps supported_ops, Type* type, Proc* proc,
346	      absl::Span<const Value> initial_values = {},
347	      ChannelConfig channel_config = ChannelConfig(),
348	      FlowControl flow_control = FlowControl::kReadyValid,
349	      ChannelStrictness strictness = kDefaultChannelStrictness,
350	      std::optional<int64_t> id = std::nullopt);
351	  absl::StatusOr<SingleValueChannel*> CreateSingleValueChannelInProc(
352	      std::string_view name, ChannelOps supported_ops, Type* type, Proc* proc,
353	      std::optional<int64_t> id = std::nullopt);
354	
355	  // Returns a span of the channels owned by the package. Sorted by channel ID.
356	  absl::Span<Channel* const> channels() const { return channel_vec_; }
357	
358	  // Returns the channel with the given ID or returns an error if no such
359	  // channel exists.
360	  absl::StatusOr<Channel*> GetChannel(int64_t id) const;
361	  absl::StatusOr<Channel*> GetChannel(std::string_view name) const;
362	
363	  // Change the name of channel 'original' to 'new_name'.
364	  //
365	  // Only valid for old-style procs (ChannelsAreProcScoped() == false).
366	  absl::Status RenameChannel(std::string_view original,
367	                             std::string_view new_name);
368	
369	  // Returns true if channels are proc scoped in this package. Returns false if
370	  // there are no channels or procs.
371	  bool ChannelsAreProcScoped() const;
372	
373	  // Returns whether there exists a channel with the given ID / name.
374	  bool HasChannelWithId(int64_t id) const {
375	    for (Channel* channel : channel_vec_) {
376	      if (channel->id() == id) {
377	        return true;
378	      }
379	    }
380	    return false;
381	  }
382	  bool HasChannelWithName(std::string_view name) const {
383	    return channels_.find(name) != channels_.end();
384	  }
385	
386	  // Removes the given channel. If the channel has any associated send/receive
387	  // nodes an error is returned.
388	  absl::Status RemoveChannel(Channel* channel);
389	
390	  // Clears all files from the package.
391	  absl::Status ClearFiles();
392	
393	  // Builder to collect overrides when cloning channels.
394	  // Each field is optional where std::nullopt indicates that the cloned channel
395	  // should share the same value as the original. If a field contains a value,
396	  // the cloned channel should ignore the original's value and use the override.
397	  class CloneChannelOverrides {
398	   public:
399	    explicit CloneChannelOverrides() = default;
400	
401	    CloneChannelOverrides& OverrideSupportedOps(ChannelOps supported_ops) {
402	      supported_ops_ = supported_ops;
403	      return *this;
404	    }
405	
406	    CloneChannelOverrides& OverrideInitialValues(
407	        absl::Span<const Value> values) {
408	      initial_values_ = values;
409	      return *this;
410	    }
411	
412	    CloneChannelOverrides& OverrideChannelConfig(ChannelConfig channel_config) {
413	      channel_config_ = channel_config;
414	      return *this;
415	    }
416	
417	    CloneChannelOverrides& OverrideFlowControl(FlowControl flow_control) {
418	      flow_control_ = flow_control;
419	      return *this;
420	    }
421	
422	    CloneChannelOverrides& OverrideStrictness(ChannelStrictness strictness) {
423	      strictness_ = strictness;
424	      return *this;
425	    }
426	
427	    std::optional<ChannelOps> supported_ops() const { return supported_ops_; }
428	    std::optional<absl::Span<const Value>> initial_values() const {
429	      return initial_values_;
430	    }
431	    std::optional<ChannelConfig> channel_config() const {
432	      return channel_config_;
433	    }
434	    std::optional<FlowControl> flow_control() const { return flow_control_; }
435	    std::optional<ChannelStrictness> strictness() const { return strictness_; }
436	
437	   private:
438	    std::optional<ChannelOps> supported_ops_;
439	    std::optional<absl::Span<const Value>> initial_values_;
440	    std::optional<ChannelConfig> channel_config_;
441	    std::optional<FlowControl> flow_control_;
442	    std::optional<ChannelStrictness> strictness_;
443	  };
444	
445	  // Clone channel, potentially from another package, with new name. Channel id
446	  // may differ from the old channel (it definitely will if it's coming from
447	  // this package).
448	  // CloneChannelOverrides is a builder class that optionally overrides fields
449	  // from the original channel.
450	  absl::StatusOr<Channel*> CloneChannel(
451	      Channel* channel, std::string_view name,
452	      const CloneChannelOverrides& overrides = CloneChannelOverrides());
453	
454	  // Returns the transform metrics aggregated across all FunctionBases.
455	  const TransformMetrics& transform_metrics() const {
456	    return transform_metrics_;
457	  }
458	  TransformMetrics& transform_metrics() { return transform_metrics_; }
459	
460	  template <typename Sink>
461	  friend void FuzzTestPrintSourceCode(Sink& sink,
462	                                      const std::unique_ptr<Package>& package) {
463	    WriteParseFunction(sink, *package);
464	  }
465	  template <typename Sink>
466	  friend void FuzzTestPrintSourceCode(Sink& sink,
467	                                      const std::shared_ptr<Package>& package) {
468	    absl::Format(&sink, "std::shared_ptr<Package>(");
469	    WriteParseFunction(sink, *package);
470	    absl::Format(&sink, ")");
471	  }
472	
473	 private:
474	  template <typename Sink>
475	  static void WriteParseFunction(Sink& sink, const Package& package) {
476	    absl::Format(&sink, "Parser::ParsePackage(R\"xls_ir(%s)xls_ir\").value()",
477	                 package.DumpIr());
478	  }
479	
480	  std::vector<std::string> GetChannelNames() const;
481	
482	  // Adds the given channel to the package.
483	  absl::Status AddChannel(std::unique_ptr<Channel> channel, Proc* proc);
484	
485	  friend class FunctionBuilder;
486	
487	  std::optional<FunctionBase*> top_;
488	
489	  // Name of this package.
490	  std::string name_;
491	
492	  // Ordinal to assign to the next node created in this package.
493	  int64_t next_node_id_ = 1;
494	
495	  std::vector<std::unique_ptr<Function>> functions_;
496	  std::vector<std::unique_ptr<Proc>> procs_;
497	  std::vector<std::unique_ptr<Block>> blocks_;
498	
499	  // Underlying manager for types used in this package.
500	  TypeManager type_manager_;
501	
502	  // The largest `Fileno` used in this `Package`.
503	  std::optional<Fileno> maximum_fileno_;
504	
505	  // Mapping of Fileno ids to string filenames, and vice-versa for reverse
506	  // lookups. These two data structures must be updated together for consistency
507	  // and should always contain the same number of entries.
508	  absl::flat_hash_map<Fileno, std::string> fileno_to_filename_;
509	  absl::flat_hash_map<std::string, Fileno> filename_to_fileno_;
510	
511	  // Channels owned by this package. Indexed by channel name. Stored as
512	  // unique_ptrs for pointer stability.
513	  absl::flat_hash_map<std::string, std::unique_ptr<Channel>> channels_;
514	
515	  // Vector of channel pointers. Kept in sync with the channels_ map. Enables
516	  // easy, stable iteration over channels.
517	  std::vector<Channel*> channel_vec_;
518	
519	  // The next channel ID to assign.
520	  int64_t next_channel_id_ = 0;
521	
522	  // Metrics which record the total number of transformations to the package.
523	  TransformMetrics transform_metrics_ = {0};
524	
525	  // Name uniquer for package entries like channels, etc. Only used if
526	  // explicitly opted into.
527	  NameUniquer package_entry_uniquer_ = NameUniquer(/*separator=*/"__");
528	};
529	
530	std::ostream& operator<<(std::ostream& os, const Package& package);
531	
532	// Implements the common idiom of:
533	// a) if top_str is given and non-empty, sets that entity as the top entity of
534	//    the package, then
535	// b) retrieve the top entity for the package
536	absl::StatusOr<FunctionBase*> FindTop(Package* p,
537	                                      std::optional<std::string_view> top_str);
538	
539	}  // namespace xls
540	
541	#endif  // XLS_IR_PACKAGE_H_
