43	class Function : public FunctionBase {
44	 private:
45	  using NodeList = std::list<std::unique_ptr<Node>>;
46	
47	 public:
48	  Function(std::string_view name, Package* package)
49	      : FunctionBase(name, package) {}
50	
51	  ~Function() override = default;
52	
53	  void MoveFrom(Function& other) {
54	    FunctionBase::MoveFrom(other);
55	    return_value_ = other.return_value();
56	    return_type_ = return_value_->GetType();
57	  }
58	
59	  void MoveParamsFrom(Function& other) {
60	    FunctionBase::MoveFrom(other, [](const Node* n) { return n->Is<Param>(); });
61	    other.params_.clear();
62	  }
63	
64	  // Returns the node that serves as the return value of this function.
65	  Node* return_value() const { return return_value_; }
66	
67	  // Return the return type from the return value, or the directly-set return
68	  // type.
