91	  }
92	  absl::Span<const AttributeData> attributes() const { return attributes_; }
93	  bool HasAttribute(AttributeKind kind) const {
94	    for (const auto& attr : attributes_) {
95	      if (attr.kind() == kind) {
96	        return true;
97	      }
98	    }
99	    return false;
100	  }
101	
102	  using FunctionBase::DumpIr;
103	  std::string DumpIr(const IrAnnotator& annotate) const override;
104	
105	  // DumpIr emits the IR in a hierarchical text format with the returned
106	  // annotations after each node definition.
107	  std::string DumpIrWithAnnotations(
108	      const std::function<std::optional<std::string>(Node*)>& annotate) const;
109	
110	  // Creates a clone of the function with the new name 'new_name'. Function is
111	  // owned by target_package.  call_remapping specifies any function
112	  // substitutions to be used in the cloned function, e.g. If call_remapping
113	  // holds {funcA, funcB}, any references to funcA in the function will be
114	  // references to funcB in the cloned function.
115	  absl::StatusOr<Function*> Clone(
116	      std::string_view new_name, Package* target_package = nullptr,
117	      const absl::flat_hash_map<const Function*, Function*>& call_remapping =
118	          {},
119	      std::optional<absl::flat_hash_map<Node*, Node*>*> original_node_to_clone =
120	          std::nullopt) const;
