101	  // transferred to the Value. DCHECK fails if not all elements are the same
102	  // type.
103	  //
104	  // Prefer using ValueBuilder for construction.
105	  static Value ArrayOwned(std::vector<Value>&& elements) {
106	    for (int64_t i = 1; i < elements.size(); ++i) {
107	      DCHECK(elements[0].SameTypeAs(elements[i]));
108	    }
