51	// A (non-owning) reference to a node; contains both the node's ID and the
52	// pointer to the node, enabling efficient access & safe comparison.
53	class NodeRef {
54	 public:
55	  explicit NodeRef(Node* node);
56	
57	  int64_t id() const { return id_; }
58	  Node* node() const { return node_; }
59	
60	  // On dereference, behaves exactly like the underlying node.
61	  Node& operator*() const { return *node_; }
62	  Node* operator->() const { return node_; }
63	
64	  friend bool operator==(const NodeRef& a, const NodeRef& b) {
65	    DCHECK(a.id() != b.id() || a.node() == b.node())
66	        << "False node match due to reused ID";
67	    return a.id() == b.id();
68	  }
69	
70	  template <typename H>
71	  friend H AbslHashValue(H h, const NodeRef& node) {
72	    return h.combine(std::move(h), node.id());
73	  }
74	
75	 private:
76	  int64_t id_;
77	  Node* node_;
78	};
79	
80	// Abstract type for a node (representing an expression) in the high level IR.
81	//
82	// Node is subtyped and can be checked-converted via the As* methods below.
83	class Node {
84	 public:
85	  virtual ~Node() = default;
86	
87	  // Accepts the visitor, instructing it to visit this node.
88	  absl::Status Accept(DfsVisitor* visitor);
89	
90	  // Visits this node with the given visitor. Visits only this node and does not
91	  // traverse the graph.
92	  absl::Status VisitSingleNode(DfsVisitor* visitor);
93	
94	  Type* GetType() const { return type_; }
95	
96	  // Precondition: this node's result type must be known to be a `BitsType`.
97	  //
98	  // Convenience helper for getting the bit count of the result type. Many
99	  // operations produce bits-typed outputs, so this is a useful helper even
100	  // though it is not properly polymorphic. It must only be called on nodes that
101	  // we are sure are producing bits-typed results.
102	  int64_t BitCountOrDie() const {
103	    return GetType()->AsBitsOrDie()->bit_count();
104	  }
105	
106	  Op op() const { return op_; }
107	  FunctionBase* function_base() const { return function_base_; }
108	  Package* package() const;
109	  const SourceInfo& loc() const { return loc_; }
110	
111	  // Returns the sequence of operands used by this node.
112	  //
113	  // Note: we make the view of the operands immutable in order to ensure that we
114	  // preserve invariants across mutations (so you can't forget to update
115	  // operand/user symmetry); e.g. see helpers ReplaceOperands() and
116	  // SwapOperands() below.
117	  absl::Span<Node* const> operands() const { return operands_; }
118	
119	  // Replaces all instances of 'old_operand' with 'new_operand', and returns
120	  // whether at least one operand was replaced.
121	  bool ReplaceOperand(Node* old_operand, Node* new_operand);
122	
123	  // Replaces the existing operand at position 'operand_no' with 'new_operand'.
124	  absl::Status ReplaceOperandNumber(int64_t operand_no, Node* new_operand,
125	                                    bool type_must_match = true);
126	
127	  // Replace all uses of this node with 'replacement', except within those users
128	  // where 'filter' returns false. If replace_implicit_uses is false implicit
129	  // uses (such as return-values/next line uses) will not be replaced.
130	  //
131	  // TODO(allight): The remove_implicit_uses should be removed once next-node is
132	  // complete since its only there because in functions using next-node there is
133	  // an implicit 'param' on the next value line internally which if it is
134	  // removed it messes up the verifier.
135	  absl::Status ReplaceUsesWith(Node* replacement,
136	                               const std::function<bool(Node*)>& filter,
137	                               bool replace_implicit_uses = true);
138	  // Replace all uses of this node with 'replacement'. If replace_implicit_uses
139	  // is false implicit uses (such as return-values/next line uses) will not be
140	  // replaced.
141	  //
142	  // TODO(allight): The remove_implicit_uses should be removed once next-node is
143	  // complete since its only there because in functions using next-node there is
144	  // an implicit 'param' on the next value line internally which if it is
145	  // removed it messes up the verifier.
146	  absl::Status ReplaceUsesWith(Node* replacement,
147	                               bool replace_implicit_uses = true) {
148	    return ReplaceUsesWith(
149	        replacement, [](Node*) { return true; }, replace_implicit_uses);
150	  }
151	
152	  // Constructs a new node and replaces all uses of 'this' with the newly
153	  // constructed node. NodeT is the node subclass (e.g., 'Param') and the
154	  // variadic args are the constructor arguments with the exception of the first
155	  // loc argument and the final Function* argument which are inherited from this
156	  // node. Returns a pointer to the newly constructed node.
157	  template <typename NodeT, typename... Args>
158	  absl::StatusOr<NodeT*> ReplaceUsesWithNew(Args&&... args) {
159	    std::unique_ptr<NodeT> new_node = std::make_unique<NodeT>(
160	        loc(), std::forward<Args>(args)..., /*name=*/"", function_base());
161	    NodeT* ptr = new_node.get();
162	    XLS_RETURN_IF_ERROR(AddNodeToFunctionAndReplace(std::move(new_node)));
163	    return ptr;
164	  }
165	
166	  // Constructs a new node, adds it to the specified stage, and replaces all
167	  // uses of 'this' with the newly constructed node. NodeT is the node subclass
168	  // (e.g., 'Param') and the variadic args are the constructor arguments with
169	  // the exception of the first loc argument and the final Function* argument
170	  // which are inherited from this node. Returns a pointer to the newly
171	  // constructed node.
172	  template <typename NodeT, typename... Args>
173	  absl::StatusOr<NodeT*> ReplaceUsesWithNewInStage(int64_t stage_index,
174	                                                   Args&&... args) {
175	    std::unique_ptr<NodeT> new_node = std::make_unique<NodeT>(
176	        loc(), std::forward<Args>(args)..., /*name=*/"", function_base());
177	    NodeT* ptr = new_node.get();
178	    XLS_RETURN_IF_ERROR(AddNodeToFunctionAndReplace(std::move(new_node),
179	                                                    /*add_to_stage=*/false));
180	    XLS_RETURN_IF_ERROR(AddNodeToStageInternal(stage_index, ptr));
181	    return ptr;
182	  }
183	
184	  // Replaces any implicit uses of this node with the given
185	  // replacement. Implicit uses include function return values and proc next
186	  // state and tokens. For example, if this node is the return value of a
187	  // function, then calling ReplaceImplicitUsesWith(foo) will make foo the
188	  // return value. Returns whether any implicit uses were replaced.
189	  absl::StatusOr<bool> ReplaceImplicitUsesWith(Node* replacement);
190	
191	  // Swaps the operands at indices 'a' and 'b' in the operands sequence.
192	  void SwapOperands(int64_t a, int64_t b);
193	
194	  // Returns true if analysis indicates that this node always produces the
195	  // same value as 'other' when run with the same operands. The analysis is
196	  // conservative and false may be returned for some "equivalent" nodes.
197	  virtual bool IsDefinitelyEqualTo(const Node* other) const;
198	
199	  // Returns whether this Op is of the template argument subclass. For example:
200	  // Is<Param>().
201	  template <typename OpT>
202	  bool Is() const {
203	    return IsOpClass<OpT>(op());
204	  }
205	
206	  // Returns a down_cast pointer of the given template argument type. CHECK
207	  // fails if the object is not of the given type. For example: As<Param>().
208	  template <typename OpT>
209	  const OpT* As() const {
210	    CHECK(Is<OpT>());
211	    return absl::down_cast<const OpT*>(this);
212	  }
213	  template <typename OpT>
214	  OpT* As() {
215	    CHECK(Is<OpT>());
216	    return absl::down_cast<OpT*>(this);
217	  }
218	
219	  // Returns whether this node was assigned a name at construction. Nodes
220	  // without assigned names will have names generated from the opcode and unique
221	  // id.
222	  bool HasAssignedName() const { return name_ != nullptr; }
223	
224	  // Returns the name of this node. If not assigned at construction time, the
225	  // name is generated from the opcode and unique id (e.g. "add.2");
226	  std::string GetName() const;
227	
228	  // Returns the name of this node, if assigned. Will be empty iff
229	  // HasAssignedName returns false.
230	  std::string_view GetNameView() const;
231	
232	  // Sets the name of this node. After this method is called. HasAssignedName
233	  // will return true.
234	  void SetName(std::string_view name);
235	
236	  // Sets the name of this node. Makes no attempt to unique-ify the name so care
237	  // must be taken that there are no collisions.
238	  void SetNameDirectly(std::string_view name);
239	
240	  // Clears the name of this node. The node will have a generate name based on
241	  // the opcode and ID. After this method is called. HasAssignedName will return
242	  // false.
243	  void ClearName();
244	
245	  // Set source location.
246	  void SetLoc(const SourceInfo& loc);
247	
248	  // Returns the name of the node and any concise supplementary information.
249	  std::string ToString() const { return ToStringInternal(false); }
250	
251	  // As above, but includes the type of the operands in the string.
252	  std::string ToStringWithOperandTypes() const {
253	    return ToStringInternal(true);
254	  }
255	
256	  // Returns a string of operand names; e.g. "[param.2, literal.7]".
257	  std::string GetOperandsString() const;
258	
259	  // Returns a string with the user of users; e.g. "{add.3, sub.7}".
260	  std::string GetUsersString() const;
261	
262	  // Comparator used for sorting by node ID.
263	  struct NodeIdLessThan {
264	    bool operator()(const Node* a, const Node* b) const {
265	      // Params may have duplicate node ids so compare pointers if id's match.
266	      // TODO(b/138805124): 2019/08/19 Figure out how to represent param uids in
267	      // the textual IR so parameters can get unique ids like all other nodes
268	      // rather than being unconditionally numbered from zero.
269	      if (a->id() == b->id()) {
270	        return a < b;
271	      }
272	      return a->id() < b->id();
273	    }
274	
275	    std::strong_ordering Compare(const Node* a, const Node* b) const {
276	      if (std::strong_ordering id_cmp = a->id() <=> b->id();
277	          id_cmp != std::strong_ordering::equal) {
278	        return id_cmp;
279	      }
280	      return a <=> b;
281	    }
282	  };
283	
284	  // Returns the unique set of users of this node sorted by id.
285	  absl::Span<Node* const> users() const { return users_; }
286	
287	  // Helper for querying whether "target" is a user of this node.
288	  bool HasUser(const Node* target) const;
289	
290	  // Returns true if the node has no explicit uses (users() is empty) and no
291	  // implicit uses (e.g., is root node of a function).
292	  bool IsDead() const;
293	
294	  // Returns true when the Op is in the list of choices
295	  bool OpIn(absl::Span<const Op> choices) const;
296	
297	  Node* operand(int64_t i) const {
298	    CHECK_LT(i, operands_.size());
299	    return operands_[i];
300	  }
301	  int64_t operand_count() const { return operands_.size(); }
302	
303	  // Returns true if target is an operand of this node.
304	  bool HasOperand(const Node* target) const;
305	
306	  // Returns the number of times that 'target' appears in the operand list of
307	  // this node.
308	  int64_t OperandInstanceCount(const Node* target) const;
309	
310	  int64_t id() const { return id_; }
311	
312	  // Sets the id of the node. Mutates the user sets of the operands of the node
313	  // because user sets are sorted by id.  Note: this should only be used by the
314	  // parser and ideally not even there.
315	  // TODO(meheff): 2021/05/05 Remove this method.
316	  void SetId(int64_t id);
317	
318	  // Clones the node with the new operands. Returns the newly created
319	  // instruction.
320	  absl::StatusOr<Node*> Clone(absl::Span<Node* const> new_operands) const {
321	    return CloneInNewFunction(new_operands, function_base());
322	  }
323	
324	  // As above but clones the instruction into the function 'new_function'. The
325	  // instruction is owned by new_function which must also contain all of
326	  // new_operands (if any).
327	  virtual absl::StatusOr<Node*> CloneInNewFunction(
328	      absl::Span<Node* const> new_operands,
329	      FunctionBase* new_function) const = 0;
330	
331	  template <typename Sink>
332	  friend void AbslStringify(Sink& sink, const Node& node) {
333	    absl::Format(&sink, "%s", node.GetName());
334	  }
335	
336	 protected:
337	  // FunctionBase needs to be a friend to access RemoveUser for deleting nodes
338	  // from the graph.
339	  friend class FunctionBase;
340	  // Block needs to be a friend to strongly name ports (guarantee name has no
341	  // uniquifying prefix).
342	  friend class Block;
343	
344	  Node(Op op, Type* type, const SourceInfo& loc, std::string_view name,
345	       FunctionBase* function);
346	
347	  std::string ToStringInternal(bool include_operand_types) const;
348	
349	  // Adds an operand to the operand list with a symmetric "user" link added to
350	  // those operands, noting that this node is a user.
351	  void AddOperand(Node* operand);
352	
353	  // Adds the set of operands 'operands'. Updating user links as with
354	  // AddOperand.
355	  void AddOperands(absl::Span<Node* const> operands);
356	
357	  // Adds an optional operand to the set of operands 'operands'. Updating user
358	  // links as with AddOperand.
359	  void AddOptionalOperand(std::optional<Node*> operand);
360	
361	  // Removes the optional operand at position 'operand_no'. Notes that this node
362	  // is no longer a user of the operand if this is its last use.
363	  absl::Status RemoveOptionalOperand(int64_t operand_no);
364	
365	  // Adds the given node to this node's function and replaces this node's uses
366	  // with the node. If add_to_stage is true and the FunctionBase is scheduled,
367	  // the replacement node is added to the same stage as the original node.
368	  absl::Status AddNodeToFunctionAndReplace(std::unique_ptr<Node> replacement,
369	                                           bool add_to_stage = true);
370	
371	  // Adds the given node to the specified stage.
372	  absl::Status AddNodeToStageInternal(int64_t stage_index, Node* node);
373	
374	  // Adds the user and returns if the user was not previously a user.
375	  bool AddUser(Node* user);
376	  void RemoveUser(Node* user);
377	
378	  // The number of users that we consider small enough to perform linear-time
379	  // algorithms on.
380	  static constexpr int64_t kSmallUserCount = 8;
381	
382	  FunctionBase* function_base_;
383	  int64_t id_;
384	  Op op_;
385	  Type* type_;
386	  SourceInfo loc_;
387	  std::unique_ptr<std::string> name_;  // Non-null if name has been assigned.
388	
389	  // Most nodes have <= 2 operands, so we keep those locally if we can.
390	  absl::InlinedVector<Node*, 2> operands_;
391	
392	  // Set of users sorted by node_id for stability.
393	  absl::InlinedVector<Node*, 2> users_;
394	};
395	
396	inline NodeRef::NodeRef(Node* node)
397	    : id_(node == nullptr ? -1 : node->id()), node_(node) {}
398	
399	inline std::ostream& operator<<(std::ostream& os, const Node& node) {
400	  os << node.ToString();
401	  return os;
402	}
403	inline std::ostream& operator<<(std::ostream& os, const Node* node) {
404	  os << (node == nullptr ? std::string("<nullptr Node*>") : node->ToString());
405	  return os;
406	}
407	inline std::ostream& operator<<(std::ostream& os, const NodeRef& node) {
408	  os << node->ToString();
409	  return os;
410	}
411	
412	inline bool operator==(const NodeRef& a, Node* b) {
413	  if (b == nullptr) {
414	    return a.node() == nullptr;
415	  }
416	  DCHECK(a.id() != b->id() || a.node() == b)
417	      << "False node match due to reused ID";
418	  return a.id() == b->id();
419	}
420	inline bool operator==(Node* a, const NodeRef& b) { return b == a; }
421	
422	}  // namespace xls
423	
424	#endif  // XLS_IR_NODE_H_
