62	// Represents a pipeline stage after scheduling.
63	class Stage {
64	 public:
65	  Stage(Node* inputs_valid, Node* outputs_ready, Node* active_inputs_valid,
66	        Node* outputs_valid)
67	      : inputs_valid_(inputs_valid),
68	        outputs_ready_(outputs_ready),
69	        active_inputs_valid_(active_inputs_valid),
70	        outputs_valid_(outputs_valid) {
71	    CHECK_EQ(inputs_valid_ == nullptr, outputs_ready_ == nullptr);
72	    CHECK_EQ(inputs_valid_ == nullptr, outputs_valid_ == nullptr);
73	  }
74	  Stage() : Stage(nullptr, nullptr, nullptr, nullptr) {}
75	
76	  Stage(const Stage& other) = default;
77	  Stage& operator=(const Stage& other) = default;
78	  Stage(Stage&& other) = default;
79	  Stage& operator=(Stage&& other) = default;
80	
81	  // Returns the set of active inputs for this stage.
82	  const absl::btree_set<Node*, Node::NodeIdLessThan>& active_inputs() const {
83	    return active_inputs_;
84	  }
85	
86	  // Returns the set of logic nodes for this stage.
87	  const absl::btree_set<Node*, Node::NodeIdLessThan>& logic() const {
88	    return logic_;
89	  }
90	
91	  // Returns the set of active outputs for this stage.
92	  const absl::btree_set<Node*, Node::NodeIdLessThan>& active_outputs() const {
93	    return active_outputs_;
94	  }
95	
96	  bool contains(Node* node) const;
97	
98	  bool AddNode(Node* node);
99	  void erase(Node* node) {
100	    active_inputs_.erase(node);
101	    logic_.erase(node);
102	    active_outputs_.erase(node);
103	  }
104	
105	  inline auto begin() {
106	    return iter::chain(active_inputs_, logic_, active_outputs_).begin();
107	  }
108	  inline auto begin() const {
109	    return iter::chain(active_inputs_, logic_, active_outputs_).begin();
110	  }
111	  inline auto end() {
112	    return iter::chain(active_inputs_, logic_, active_outputs_).end();
113	  }
114	  inline auto end() const {
115	    return iter::chain(active_inputs_, logic_, active_outputs_).end();
116	  }
117	
118	  absl::StatusOr<Stage> Clone(
119	      const absl::flat_hash_map<Node*, Node*>& node_mapping) const;
120	
121	  bool IsControlled() const {
122	    return inputs_valid_ != nullptr && outputs_ready_ != nullptr &&
123	           active_inputs_valid_ != nullptr && outputs_valid_ != nullptr;
124	  }
125	
126	  // Returns the node that signals whether it would be valid for this stage to
127	  // execute; i.e., that all passive inputs are updated for the next activation.
128	  Node* inputs_valid() const { return inputs_valid_; }
129	
130	  void set_inputs_valid(Node* inputs_valid) { inputs_valid_ = inputs_valid; }
131	
132	  // Returns the node that signals whether it is safe for this stage to execute;
133	  // i.e., that the receiver for all passive outputs will have space to store
134	  // the data.
135	  Node* outputs_ready() const { return outputs_ready_; }
136	
137	  void set_outputs_ready(Node* outputs_ready) {
138	    outputs_ready_ = outputs_ready;
139	  }
140	
141	  // Returns the node that signals whether all active inputs to this stage are
142	  // valid; i.e., that all active receives & all actively-read state values have
143	  // the correct values for this activation.
144	  Node* active_inputs_valid() const { return active_inputs_valid_; }
145	
146	  void set_active_inputs_valid(Node* active_inputs_valid) {
147	    active_inputs_valid_ = active_inputs_valid;
148	  }
149	
150	  // Returns the node that signals whether it would be safe for this stage to be
151	  // done executing; i.e., that all logic nodes are updated by the current
152	  // activation, and all active outputs have completed execution.
153	  Node* outputs_valid() const { return outputs_valid_; }
154	
155	  void set_outputs_valid(Node* outputs_valid) {
156	    outputs_valid_ = outputs_valid;
157	  }
158	
159	  bool DependsOn(Node* node) const;
160	
161	 private:
162	  absl::btree_set<Node*, Node::NodeIdLessThan> active_inputs_;
163	  absl::btree_set<Node*, Node::NodeIdLessThan> logic_;
164	  absl::btree_set<Node*, Node::NodeIdLessThan> active_outputs_;
165	  Node* inputs_valid_ = nullptr;
166	  Node* outputs_ready_ = nullptr;
167	  Node* active_inputs_valid_ = nullptr;
168	  Node* outputs_valid_ = nullptr;
169	};
