176	 public:
177	  enum class Kind {
178	    kFunction,
179	    kProc,
180	    kBlock,
181	  };
182	  template <typename Sink>
183	  friend void AbslStringify(Sink& sink, const Kind& k) {
184	    switch (k) {
185	      case Kind::kFunction:
186	        absl::Format(&sink, "function");
187	        return;
