239	  virtual std::vector<std::string> AttributeIrStrings() const;
240	
241	  // Return Span of parameters.
242	  absl::Span<Param* const> params() const { return params_; }
243	
244	  // Return the parameter at the given index.
245	  Param* param(int64_t index) const { return params_.at(index); }
246	
247	  // Return the parameter with the given name.
248	  absl::StatusOr<Param*> GetParamByName(std::string_view param_name) const;
249	
250	  absl::StatusOr<int64_t> GetParamIndex(Param* param) const;
251	
252	  absl::Span<Next* const> next_values() const { return next_values_; }
253	
254	  const absl::btree_set<Next*, Node::NodeIdLessThan>& next_values(
255	      StateElement* state_element) const {
256	    if (!next_values_by_state_element_.contains(state_element)) {
257	      static const absl::NoDestructor<
258	          absl::btree_set<Next*, Node::NodeIdLessThan>>
259	          kEmptySet;
260	      // This should be pretty rare. Basically this should only happen in the
261	      // short time before the non-updated state element is replaced. Just
262	      // returning what is actually there is nicer than crashing however. Do
263	      // check that this is not just some sort of weird corruption however.
264	      CHECK(absl::c_none_of(nodes(),
265	                            [state_element](Node* n) {
266	                              return n->Is<Next>() &&
267	                                     n->As<Next>()->state_element() ==
268	                                         state_element;
269	                            }))
270	          << "Invalid side table for next values. Missing " << state_element
271	          << " in " << this;
272	      return *kEmptySet;
273	    }
274	    return next_values_by_state_element_.at(state_element);
275	  }
