500	  // Moves only the actual logic from `other`; not the params, state elements,
501	  // channels, or proc instantiations. The move includes the staging of the
502	  // logic, if this is a scheduled entity.
503	  void MoveLogicFrom(FunctionBase& other) {
504	    MoveFrom(other, [](const Node* n) {
505	      // We can't move Params because they're part of a function's interface.
506	      // Procs broadly assume that StateReads will exist in a close 1-1
507	      // association with their StateElements, so it's simpler to keep them
508	      // together.
509	      return !n->Is<Param>() && !n->Is<StateRead>();
510	    });
511	    other.next_values_by_state_element_.clear();
512	    other.next_values_.clear();
513	  }
